import React, { useState } from 'react';
import { ArrowLeftRight, Volume2, Copy, Check, Sparkles, BookPlus, RefreshCw } from 'lucide-react';
import { translateText, detectLanguage, textToSpeech, addVocab } from '../services/api';

const TranslationTool = ({ languages, selectedLang, username }) => {
  const [sourceLang, setSourceLang] = useState('auto');
  const [targetLang, setTargetLang] = useState(selectedLang || 'es');
  const [inputText, setInputText] = useState('');
  const [translatedText, setTranslatedText] = useState('');
  const [detectedMeta, setDetectedMeta] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isCopied, setIsCopied] = useState(false);
  const [isSavedVocab, setIsSavedVocab] = useState(false);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);

  const handleTranslate = async () => {
    if (!inputText.trim()) return;
    setIsLoading(true);
    setIsCopied(false);
    setIsSavedVocab(false);

    try {
      // 1. Detect language if auto
      let actualSource = sourceLang;
      if (sourceLang === 'auto') {
        const det = await detectLanguage(inputText);
        setDetectedMeta(det);
        actualSource = det.code;
      } else {
        setDetectedMeta(null);
      }

      // 2. Perform translation
      const res = await translateText(inputText, targetLang, actualSource === 'auto' ? null : actualSource);
      setTranslatedText(res.translated_text);
    } catch (e) {
      console.error("Translation error:", e);
      setTranslatedText("Translation error. Please check backend server connection.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSwap = () => {
    if (sourceLang === 'auto') {
      if (detectedMeta) {
        setSourceLang(targetLang);
        setTargetLang(detectedMeta.code);
      } else {
        setSourceLang(targetLang);
        setTargetLang('en');
      }
    } else {
      const temp = sourceLang;
      setSourceLang(targetLang);
      setTargetLang(temp);
    }

    if (translatedText) {
      setInputText(translatedText);
      setTranslatedText(inputText);
    }
  };

  const handleCopy = () => {
    if (!translatedText) return;
    navigator.clipboard.writeText(translatedText);
    setIsCopied(true);
    setTimeout(() => setIsCopied(false), 2000);
  };

  const handlePlayAudio = async () => {
    if (!translatedText) return;
    setIsPlayingAudio(true);
    try {
      const audioUrl = await textToSpeech(translatedText, targetLang);
      const audio = new Audio(audioUrl);
      audio.onended = () => setIsPlayingAudio(false);
      await audio.play();
    } catch (e) {
      console.error("Audio playback error:", e);
      setIsPlayingAudio(false);
    }
  };

  const handleSaveToVocab = async () => {
    if (!inputText || !translatedText) return;
    try {
      await addVocab(username, translatedText, targetLang, inputText);
      setIsSavedVocab(true);
      setTimeout(() => setIsSavedVocab(false), 2500);
    } catch (e) {
      console.error("Error saving vocabulary:", e);
    }
  };

  const samplePhrases = [
    "Hello! How are you today?",
    "Where is the nearest restaurant?",
    "Thank you very much for your help.",
    "It is a pleasure to meet you."
  ];

  return (
    <div className="glass-panel" style={{ flex: 1, display: 'flex', flexDirection: 'column', padding: '24px', gap: '20px', overflowY: 'auto' }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderBottom: '1px solid rgba(255, 255, 255, 0.1)', paddingBottom: '16px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div style={{ background: 'linear-gradient(135deg, #8b5cf6, #ec4899)', padding: '10px', borderRadius: '12px' }}>
            <Sparkles size={20} color="#fff" />
          </div>
          <div>
            <h2 style={{ fontSize: '18px', fontWeight: 700, color: '#fff' }}>Neural Translation Studio</h2>
            <p style={{ fontSize: '12px', color: '#9ca3af' }}>Multi-directional translation across 51 world languages</p>
          </div>
        </div>
        <span className="badge-tag">51 Languages Active</span>
      </div>

      {/* Language Selection Row */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '12px', flexWrap: 'wrap' }}>
        {/* Source Language */}
        <select 
          value={sourceLang}
          onChange={(e) => setSourceLang(e.target.value)}
          style={{
            flex: 1,
            minWidth: '160px',
            background: 'rgba(30, 41, 59, 0.9)',
            border: '1px solid rgba(255, 255, 255, 0.15)',
            borderRadius: '10px',
            padding: '10px 14px',
            color: '#fff',
            fontSize: '14px',
            outline: 'none',
            cursor: 'pointer'
          }}
        >
          <option value="auto">✨ Auto Detect Language</option>
          {Object.entries(languages || {}).map(([code, meta]) => (
            <option key={code} value={code}>
              {meta.flag} {meta.name} ({meta.native})
            </option>
          ))}
        </select>

        {/* Swap Button */}
        <button 
          onClick={handleSwap}
          className="icon-action-btn"
          title="Swap source and target languages"
          style={{ padding: '10px 14px', borderRadius: '10px' }}
        >
          <ArrowLeftRight size={18} />
        </button>

        {/* Target Language */}
        <select 
          value={targetLang}
          onChange={(e) => setTargetLang(e.target.value)}
          style={{
            flex: 1,
            minWidth: '160px',
            background: 'rgba(30, 41, 59, 0.9)',
            border: '1px solid rgba(255, 255, 255, 0.15)',
            borderRadius: '10px',
            padding: '10px 14px',
            color: '#fff',
            fontSize: '14px',
            outline: 'none',
            cursor: 'pointer'
          }}
        >
          {Object.entries(languages || {}).map(([code, meta]) => (
            <option key={code} value={code}>
              {meta.flag} {meta.name} ({meta.native})
            </option>
          ))}
        </select>
      </div>

      {/* Translation Workspace Grid */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px', flex: 1 }}>
        {/* Source Box */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span style={{ fontSize: '12px', color: '#9ca3af', fontWeight: 500 }}>
              Input Text {detectedMeta && <span style={{ color: '#c084fc' }}>(Detected: {detectedMeta.name})</span>}
            </span>
            <span style={{ fontSize: '11px', color: '#6b7280' }}>{inputText.length} chars</span>
          </div>

          <textarea 
            placeholder="Enter text, paragraph, or phrase to translate..."
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            style={{
              flex: 1,
              minHeight: '200px',
              background: 'rgba(15, 23, 42, 0.8)',
              border: '1px solid rgba(255, 255, 255, 0.15)',
              borderRadius: '12px',
              padding: '14px',
              color: '#fff',
              fontSize: '14px',
              lineHeight: '1.6',
              resize: 'none',
              outline: 'none'
            }}
          />

          <button 
            onClick={handleTranslate} 
            disabled={isLoading || !inputText.trim()}
            className="glow-btn"
            style={{ marginTop: '8px', padding: '12px' }}
          >
            {isLoading ? <RefreshCw size={16} className="animate-spin" /> : <Sparkles size={16} />}
            <span>{isLoading ? 'Translating...' : 'Translate Now'}</span>
          </button>
        </div>

        {/* Output Box */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span style={{ fontSize: '12px', color: '#9ca3af', fontWeight: 500 }}>
              Target Output ({languages[targetLang]?.name || targetLang})
            </span>
          </div>

          <div 
            style={{
              flex: 1,
              minHeight: '200px',
              background: 'rgba(30, 41, 59, 0.6)',
              border: '1px solid rgba(255, 255, 255, 0.12)',
              borderRadius: '12px',
              padding: '14px',
              color: translatedText ? '#fff' : '#9ca3af',
              fontSize: '15px',
              lineHeight: '1.6',
              userSelect: 'text',
              direction: languages[targetLang]?.dir === 'rtl' ? 'rtl' : 'ltr',
              textAlign: languages[targetLang]?.dir === 'rtl' ? 'right' : 'left'
            }}
          >
            {translatedText || "Translation output will appear here..."}
          </div>

          {/* Action Toolbar */}
          {translatedText && (
            <div style={{ display: 'flex', gap: '8px', marginTop: '8px', flexWrap: 'wrap' }}>
              <button onClick={handlePlayAudio} className="icon-action-btn">
                <Volume2 size={15} color={isPlayingAudio ? "#ec4899" : "#9ca3af"} />
                <span>{isPlayingAudio ? 'Playing...' : 'Pronunciation'}</span>
              </button>

              <button onClick={handleCopy} className="icon-action-btn">
                {isCopied ? <Check size={15} color="#10b981" /> : <Copy size={15} />}
                <span>{isCopied ? 'Copied!' : 'Copy Text'}</span>
              </button>

              <button onClick={handleSaveToVocab} className="icon-action-btn">
                {isSavedVocab ? <Check size={15} color="#10b981" /> : <BookPlus size={15} />}
                <span>{isSavedVocab ? 'Saved to SM-2' : 'Save to Vocab'}</span>
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Preset Phrases */}
      <div style={{ borderTop: '1px solid rgba(255, 255, 255, 0.1)', paddingTop: '14px' }}>
        <div style={{ fontSize: '12px', color: '#9ca3af', marginBottom: '8px' }}>Try common phrases:</div>
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
          {samplePhrases.map((phrase, i) => (
            <button 
              key={i}
              onClick={() => { setInputText(phrase); }}
              className="icon-action-btn"
              style={{ fontSize: '12px' }}
            >
              "{phrase}"
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default TranslationTool;
